    return [{"json": {**base, "route": "mineru"}}]
if mime.startswith("text/"):
    return [{"json": {**base, "route": "text"}}]
if mime.startswith("image/"):
    return [{"json": {**base, "route": "image"}, "binary": first.binary}]
if mime.startswith("audio/"):
    return [{"json": {**base, "route": "audio"}, "binary": first.binary}]
if mime.startswith("video/"):
    return [{"json": {**base, "route": "video"}, "binary": first.binary}]
return []

