items = _input.all()
trigger_json = _("Notion Trigger").item.json
page_id = trigger_json.get("id", "")
props = trigger_json.get("properties", {})
name_title = (props.get("Name") or {}).get("title") or []
page_title = ""
if name_title:
    page_title = name_title[0].get("plain_text", "") or (name_title[0].get("text") or {}).get("content", "")
modified_time = trigger_json.get("last_edited_time", "")

base_meta = {
    "source": "notion",
    "fileId": page_id,
    "fileName": page_title,
    "modifiedTime": modified_time,
    "parsed_by": "notion_blocks",
}

def rt2s(arr):
    if not isinstance(arr, list):
        return ""
    return "".join(
        r.get("plain_text", "") or (r.get("text") or {}).get("content", "")
        for r in arr
    )

def get_media_url(block_data):
    if block_data.get("type") == "file":
        return (block_data.get("file") or {}).get("url", "")
    if block_data.get("type") == "external":
        return (block_data.get("external") or {}).get("url", "")
    return (block_data.get("file") or {}).get("url", "") or (block_data.get("external") or {}).get("url", "")

text_parts = []
media_items = []

TEXT_BLOCKS = {
    "paragraph", "heading_1", "heading_2", "heading_3",
    "bulleted_list_item", "numbered_list_item", "to_do",
    "toggle", "quote", "callout", "code", "table_row",
}

for item in items:
    j = item.json or {}
    bt = j.get("type")
    if not bt:
        continue
    b = j.get(bt) or {}

    if bt in TEXT_BLOCKS:
        for key in ("rich_text", "title", "caption"):
            arr = b.get(key)
            if isinstance(arr, list):
                s = rt2s(arr).strip()
                if s:
                    text_parts.append(s)
                break

    elif bt == "image":
        url = get_media_url(b)
        if url:
            caption = rt2s(b.get("caption", []))
            media_items.append({**base_meta, "route": "image", "downloadUrl": url, "caption": caption, "media_type": "image"})

    elif bt == "audio":
        url = get_media_url(b)
        if url:
            media_items.append({**base_meta, "route": "audio", "downloadUrl": url, "media_type": "audio"})

    elif bt == "video":
        url = get_media_url(b)
        if url:
            media_items.append({**base_meta, "route": "video", "downloadUrl": url, "media_type": "video"})

    elif bt in ("file", "pdf"):
        url = get_media_url(b)
        if url:
            caption = rt2s(b.get("caption", []))
            media_items.append({**base_meta, "route": "file", "downloadUrl": url, "caption": caption, "media_type": "file"})

    elif bt in ("embed", "bookmark"):
        url = b.get("url", "")
        if url:
            text_parts.append(f"[Link: {url}]")

result = [{"json": {**base_meta, "content": "\n".join(text_parts), "route": "text", "media_type": "text"}}]
for m in media_items:
    result.append({"json": m})
return result

