import base64

item = _input.first()
j = item.json or {}
binary = item.binary if hasattr(item, "binary") else {}
route_json = _("Route — Notion File").item.json
content = ""

# Try to decode binary as UTF-8 text
if binary and "data" in binary:
    raw = binary["data"].get("data", "")
    if raw:
        try:
            content = base64.b64decode(raw).decode("utf-8", errors="replace")
        except Exception:
            content = ""

if not content:
    caption = route_json.get("caption", "")
    content = f"[Attached file: {route_json.get('fileName', 'unknown')}]"
    if caption:
        content += f" Caption: {caption}"

return [{"json": {
    "content": content,
    "media_type": "file",
    "source": "notion",
    "fileId": route_json.get("fileId", ""),
    "fileName": route_json.get("fileName", ""),
    "modifiedTime": route_json.get("modifiedTime", ""),
    "parsed_by": "notion_file_download",
}}]
